package com.bank.platform;

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.math.BigDecimal;
import java.util.logging.*;

public class RuntimeInspector {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository repo = new AccountRepository();
        TransferService service = new TransferService(repo);
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));

        // Same bytecode; these values differ per JVM IMPLEMENTATION.
        log.info(() -> "JVM name   : " + System.getProperty("java.vm.name"));
        log.info(() -> "JVM vendor : " + System.getProperty("java.vm.vendor"));
        log.info(() -> "OS/arch    : " + System.getProperty("os.name")
                        + " / " + System.getProperty("os.arch"));
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            log.info(() -> "Active GC  : " + gc.getName());
        }
    }
}

